const cfg = $('Configuração — Edite Aqui').first().json;
const TEMAS = [
  { id: 'ramal-remoto', titulo: 'Ramal em qualquer lugar', fatos: 'PABX IP na nuvem (ConnectX). O ramal funciona no computador ou no celular, com o mesmo número, de casa, da filial ou da rua. Sem equipamento para manter no escritório.' },
  { id: 'fixo-movel', titulo: 'Ligações por valor fixo', fatos: 'Ligações ilimitadas para fixos e celulares por valor fixo, ligações internas sem custo entre a equipe e número fixo de outras cidades.' },
  { id: 'slack-zoho', titulo: 'Slack + Zoho Desk', fatos: 'Integração que transforma conversas do Slack em tickets e comentários no Zoho Desk. Conversas normais ficam em um ticket por canal por dia; uma thread abre um ticket próprio com o título da mensagem original. Imagens viram anexos.' },
  { id: 'monitoramento', titulo: 'Monitoramento 24/7', fatos: 'Monitoramento contínuo de conectividade, serviços e servidores, para agir antes de o cliente perceber o problema.' },
  { id: 'consultoria', titulo: 'Consultoria de TI', fatos: 'Visão externa, identificação de problemas ocultos e tempo devolvido para a equipe.' },
  { id: 'integracoes-crm', titulo: 'CRM e mensagens corporativas', fatos: 'Integrações entre CRMs e aplicativos de mensagens corporativas, sem copiar e colar entre sistemas.' },
  { id: 'portaria', titulo: 'Portaria remota', fatos: 'Atendimento e liberação de acesso à distância integrados ao PABX IP.' },
  { id: 'sistemas', titulo: 'Sistemas e aplicativos sob medida', fatos: 'Desenvolvimento de sites, sistemas web, aplicativos e integrações construídos junto com a operação do cliente.' }
];

// Rodízio simples guardado no próprio workflow (funciona nas execuções automáticas).
const sd = $getWorkflowStaticData('global');
const i = Number.isInteger(sd.temaIdx) ? sd.temaIdx : 0;
const tema = TEMAS[i % TEMAS.length];
sd.temaIdx = (i + 1) % TEMAS.length;
const site = String((cfg.SITE_URL ?? 'https://conectxip.com')).replace(/\/+$/, '');
return [{ json: { tema, site, imagem: String(cfg.SOCIAL_IMAGE_URL ?? '').trim() } }];

const cfg = $('Configuração — Edite Aqui').first().json;
const base = $('Escolhe Tema (rodízio)').first().json;
const { tema, site, imagem } = base;
const resp = $input.first().json;

// 1) Tenta ler o JSON gerado pela IA
let ia = null;
try {
  const texto = (resp.content || []).map(c => c.text || '').join('').trim()
    .replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  const j = JSON.parse(texto);
  if (j && j.linkedin && j.facebook && j.instagram) ia = j;
} catch (e) { ia = null; }

// 2) Plano B sem IA: texto fixo e seguro, só com os fatos do tema
const cta = 'Conheça a ConectPbx.';
const plano = {
  linkedin: `${tema.titulo}\n\n${tema.fatos}\n\n${cta}`,
  facebook: `${tema.titulo}: ${tema.fatos} ${cta}`,
  instagram: `${tema.titulo}\n\n${tema.fatos}\n\n${cta}`,
  hashtags: ['telefoniaIP', 'PABX', 'TI', 'ConectPbx']
};
const src = ia || plano;
const fonte = ia ? 'ia' : 'plano_b';

const tags = (Array.isArray(src.hashtags) ? src.hashtags : plano.hashtags)
  .map(t => String(t).replace(/[^\p{L}\p{N}_]/gu, '')).filter(Boolean).slice(0, 6)
  .map(t => '#' + t).join(' ');

const url = rede => `${site}/?utm_source=${rede}&utm_medium=social&utm_campaign=${encodeURIComponent(tema.id)}`;
const corta = (s, n) => { s = String(s); return s.length <= n ? s : s.slice(0, n - 1).trimEnd() + '…'; };

const linkedin  = corta(`${src.linkedin}\n\n${url('linkedin')}\n\n${tags}`, 2900);
const facebook  = corta(`${src.facebook}\n\n${tags}`, 1800);
const instagram = corta(`${src.instagram}\n\nLink na bio.\n\n${tags}`, 2100);

return [{ json: {
  tema, fonte, imagem, tags,
  linkedin, facebook, instagram,
  facebookLink: url('facebook'),
  temImagem: /^https:\/\//i.test(imagem),
  aprovacao: String(cfg.SOCIAL_APPROVAL ?? 'true').toLowerCase() === 'true'
} }];

const get = nome => { try { return $(nome).first().json; } catch (e) { return null; } };
const ok = (j, campo) => !!(j && !j.error && !j.errorMessage && (campo ? j[campo] : true));
const li = get('LinkedIn — Publicar');
const fb = get('Facebook — Publicar na Página');
const igc = get('Instagram — Criar Mídia');
const igp = get('Instagram — Publicar');
const post = get('Monta Posts');
const prep = get('LinkedIn — Preparar Texto');

const linhas = [
  `LinkedIn: ${(prep && prep.pular) ? 'FALHOU (' + prep.motivo + ')' : (ok(li) ? 'publicado' : 'FALHOU')}`,
  `Facebook: ${ok(fb, 'id') ? 'publicado' : 'FALHOU'}`,
  `Instagram: ${post && !post.temImagem ? 'ignorado (sem imagem em SOCIAL_IMAGE_URL)' : (ok(igc, 'id') && ok(igp, 'id') ? 'publicado' : 'FALHOU')}`
];
const houveFalha = linhas.some(l => l.includes('FALHOU'));
const html = `<div style="font-family:Arial,sans-serif;color:#0c1729"><p><b>${houveFalha ? 'Alguma rede falhou' : 'Divulgação concluída'}</b>: ${String(post?.tema?.titulo || '')}</p><p style="white-space:pre-line">${linhas.join('\n')}</p>${houveFalha ? '<p style="color:#667;font-size:12px">Confira a execução no n8n para ver o erro de cada rede.</p>' : ''}</div>`;
return [{ json: { tema: post?.tema?.titulo, fonte: post?.fonte, resumo: linhas.join('\n'), houveFalha, html } }];

const cfg = $('Configuração — Edite Aqui').first().json;
// Texto no formato do LinkedIn ("little text"): caracteres reservados precisam de barra.
// O "#" fica sem escape para as hashtags funcionarem.
const post = $('Monta Posts').first().json;
const escapa = s => String(s).replace(/([\\|{}@\[\]()<>*_~])/g, '\\$1');
let author = String(cfg.LINKEDIN_AUTHOR_URN ?? '').trim();
if (!author) {
  try { const me = $('LinkedIn — Descobrir Meu ID').first().json; if (me && me.sub) author = 'urn:li:person:' + me.sub; } catch (e) {}
}
if (!/^urn:li:(person|organization):[A-Za-z0-9_-]+$/.test(author)) {
  // Não derruba o fluxo: o LinkedIn é pulado e o motivo aparece aqui e no e-mail de resultado.
  return [{ json: { pular: true, motivo: 'Autor do LinkedIn indefinido. Confira a credencial (escopos openid profile w_member_social) ou preencha LINKEDIN_AUTHOR_URN no nó Configuração — Edite Aqui.' } }];
}
return [{ json: {
  author,
  version: String(cfg.LINKEDIN_API_VERSION ?? '202608'),
  body: {
    author,
    commentary: escapa(post.linkedin).slice(0, 3000),
    visibility: 'PUBLIC',
    distribution: { feedDistribution: 'MAIN_FEED', targetEntities: [], thirdPartyDistributionChannels: [] },
    lifecycleState: 'PUBLISHED',
    isReshareDisabledByAuthor: false
  }
} }];

const post = $('Monta Posts').first().json;
const h = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\n/g,'<br>');
const bloco = (titulo, texto) => `<h3 style="margin:18px 0 6px;font-size:15px">${titulo}</h3><div style="padding:12px 14px;background:#f4f6fa;border-radius:8px;font-size:14px;line-height:1.5">${h(texto)}</div>`;
const link = $execution.resumeUrl;
const html = `<div style="font-family:Arial,sans-serif;max-width:640px;color:#0c1729">
<p style="font-size:15px">Post para aprovar: <b>${h(post.tema.titulo)}</b> <span style="color:#667">(texto: ${post.fonte === 'ia' ? 'gerado por IA' : 'plano B, sem IA'})</span></p>
${bloco('LinkedIn', post.linkedin)}${bloco('Facebook', post.facebook)}${bloco('Instagram' + (post.temImagem ? '' : ' (sem imagem, será ignorado)'), post.instagram)}
<p style="margin:26px 0 8px"><a href="${link}" style="background:#e4570f;color:#fff;padding:12px 22px;border-radius:8px;text-decoration:none;font-weight:bold">Aprovar e publicar</a></p>
<p style="font-size:12px;color:#667">Para não publicar, ignore este e-mail. O rascunho expira em 48 horas. Não encaminhe este e-mail: quem tiver o link consegue aprovar.</p></div>`;
return [{ json: { assunto: `[Aprovar post] ${post.tema.titulo}`, html } }];

// EDITE AQUI: todas as configurações do workflow ficam neste nó (não precisa de "Variables" do n8n).
const CONFIG = {
  // Site e conteúdo
  SITE_URL: 'https://conectxip.com',
  SOCIAL_IMAGE_URL: '',            // imagem pública https para o Instagram (vazio = pula o Instagram)
  SOCIAL_AI_MODEL: 'claude-sonnet-5-5',

  // Aprovação por e-mail (Gmail)
  SOCIAL_APPROVAL: 'true',         // 'true' pede aprovação; 'false' publica direto
  SOCIAL_APPROVER_EMAIL: 'seu-email@gmail.com',

  // LinkedIn
  LINKEDIN_AUTHOR_URN: '',         // vazio = usa o seu perfil automaticamente; ou urn:li:organization:NNNN
  LINKEDIN_API_VERSION: '202608',

  // Facebook e Instagram (IDs do Graph API)
  FACEBOOK_PAGE_ID: '',
  INSTAGRAM_USER_ID: ''
};
return [{ json: CONFIG }];
